PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE fleet_timeseries (
    id             INTEGER PRIMARY KEY AUTOINCREMENT,
    ts             TEXT NOT NULL,
    agent_id       TEXT NOT NULL,
    role           TEXT,
    system         TEXT,
    docked         INTEGER,
    credits        REAL,
    fuel           REAL,
    max_fuel       REAL,
    cargo_used     REAL,
    cargo_capacity REAL
);
COMMIT;
